questionvariables.text:
wordlength1:rand([6,7,8]);
word_1:if wordlength1 = 6 then 2 elseif wordlength1=7 then 3 else 4;
word_2:if wordlength1 = 6 then 4 elseif wordlength1=7 then 5 else 6;
word_3:if wordlength1 = 6 then "Two" elseif wordlength1=7 then "Three" else "Four";
word_4:if wordlength1 = 6 then "Four" elseif wordlength1=7 then "Five" else "Six";
word1:if wordlength1 = 6 then rand([BETTER, BEYOND, BISHOP, BORDER, BOTTLE, BOTTOM]) elseif wordlength1=7 then rand([CALLING, ANSWERS, GALLERY, GROWING, PROGRAM, TRUDGED]) else rand([SYLLABUS, RANDOMLY, FRIENDLY, ABSTRACT, SCULPTED, THANKFUL]);
n_space1:binomial(8, 4);
n_space2:binomial(7, 3);
n_space3:binomial(6, 2);
ta_1:if wordlength1 = 8 then n_space1 elseif wordlength1 = 7 then n_space2 else n_space3;
n_event1:binomial(6, 4);
n_event2:binomial(5, 3);
n_event3:binomial(4, 2);
ta_2:if wordlength1 = 8 then n_event1 elseif wordlength1 = 7 then n_event2 else n_event3;
prob_event1:n_event1/n_space1;
prob_event2:n_event2/n_space2;
prob_event3:n_event3/n_space3;
word_4:if wordlength1 = 6 then "both " elseif wordlength1=7 then "all the Three" else "all the Four";

ta:if wordlength1 = 8 then prob_event1 elseif wordlength1 = 7 then prob_event2 else prob_event3;
